package wirestack_m8_001_consumer

import wirestack.net.*
import wirestack as api

main(): Int64 {
    let address = api.IpAddress(api.IpAddressFamily.Ipv4, [127u8, 0u8, 0u8, 1u8])
    let endpoint = api.SocketEndpoint(address, 8080u16)
    let source = api.CancellationSource()
    source.cancel()
    var allCorrect = true
    for (kind in 0..2) {
        let stream = TcpStream.connect(endpoint, context: api.OperationContext(
            deadline: Some(api.Deadline.after(3 * Duration.second))))
        let context = if (kind == 0) {
            api.OperationContext(cancellation: source.token)
        } else {
            api.OperationContext(deadline: Some(api.Deadline.after(0 * Duration.second)))
        }
        var rejected = false
        try {
            try {
                stream.close(context: context)
            } catch (error: api.NetworkException) {
                rejected = match ((kind, error.code)) {
                    case (0, api.NetworkErrorCode.Cancelled) => true
                    case (1, api.NetworkErrorCode.TimedOut) => true
                    case _ => false
                }
                match (error.phase) {
                    case api.NetworkPhase.TransportClose => ()
                    case _ => throw IllegalStateException("wrong close phase")
                }
                if (internetPort(error.remoteEndpoint) != 8080u16 ||
                    internetPort(error.localEndpoint) == 0u16) {
                    throw IllegalStateException("stopped close lost endpoint diagnostics")
                }
            }
            let stillOpen = match (stream.state) {
                case SocketState.Open => !stream.isClosed()
                case _ => false
            }
            println("STOPPED_CLOSE case=${kind} rejected=${rejected} open=${stillOpen}")
            if (rejected && stillOpen) {
                stream.writeAll(api.ByteSpan([0x42u8]), context: api.OperationContext(
                    deadline: Some(api.Deadline.after(3 * Duration.second))))
            } else {
                allCorrect = false
            }
        } finally {
            stream.close()
        }
    }
    if (allCorrect) { 0 } else { 42 }
}

func internetPort(endpoint: ?api.NetworkEndpoint): UInt16 {
    match (endpoint) {
        case Some(api.NetworkEndpoint.Internet(value)) => value.port
        case _ => throw IllegalStateException("expected captured Internet endpoint")
    }
}
